import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const projectRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sourceRoot = path.join(projectRoot, "src");
const outputPath = path.join(projectRoot, "dist", "Nebula.lua");
const entryName = "NebulaCore";

function comparePaths(left, right) {
  return left < right ? -1 : left > right ? 1 : 0;
}

function collectLuaFiles(directory) {
  return fs
    .readdirSync(directory, { withFileTypes: true })
    .flatMap((entry) => {
      const absolutePath = path.join(directory, entry.name);
      if (entry.isDirectory()) return collectLuaFiles(absolutePath);
      return entry.isFile() && entry.name.endsWith(".lua") ? [absolutePath] : [];
    })
    .sort(comparePaths);
}

function toModuleId(relativePath) {
  return relativePath
    .replaceAll(path.sep, "/")
    .replace(/\.lua$/, "")
    .split("/")
    .join(".");
}

function resolveDependency(moduleId, expression) {
  const resolved = moduleId === entryName ? [] : moduleId.split(".");
  const segments = expression
    .slice("script".length)
    .split(".")
    .filter(Boolean);

  for (const segment of segments) {
    if (segment === "Parent") {
      if (resolved.length === 0) {
        throw new Error(`require() walks above the package root in ${moduleId}.lua`);
      }
      resolved.pop();
    } else {
      resolved.push(segment);
    }
  }

  return resolved.join(".");
}

function rewriteRequires(source, moduleId, moduleIds) {
  const dependencies = new Set();
  const requireExpression =
    /require\(\s*(script(?:\.[A-Za-z_][A-Za-z0-9_]*)+)\s*\)/g;

  const rewritten = source
    .replace(requireExpression, (_match, expression) => {
      const dependencyId = resolveDependency(moduleId, expression);
      if (!moduleIds.has(dependencyId)) {
        throw new Error(
          `${moduleId}.lua references missing module ${dependencyId}`,
        );
      }
      dependencies.add(dependencyId);
      return `require(${JSON.stringify(dependencyId)})`;
    })
    .replace(/^\s*export\s+type\s+/gm, "type ");

  if (/\brequire\s*\(\s*script(?:\.|\s|\))/i.test(rewritten)) {
    throw new Error(`Unbundled require() found in ${moduleId}.lua`);
  }

  const unsupportedRequire = rewritten.match(
    /\brequire\s*\(\s*(?!["'])[^)]*\)/,
  );
  if (unsupportedRequire) {
    throw new Error(
      `Unsupported dependency expression in ${moduleId}.lua: ${unsupportedRequire[0]}`,
    );
  }

  return {
    source: rewritten.replace(/^\s*--!strict\s*\n/, ""),
    dependencies: [...dependencies].sort(comparePaths),
  };
}

function loadSources() {
  const files = collectLuaFiles(sourceRoot).filter(
    (file) => path.basename(file) !== "Nebula.lua",
  );
  const sources = new Map();

  for (const file of files) {
    const relativePath = path.relative(sourceRoot, file);
    sources.set(toModuleId(relativePath), fs.readFileSync(file, "utf8"));
  }

  if (!sources.has(entryName)) {
    throw new Error(`Missing src/${entryName}.lua bundle entry source`);
  }

  return sources;
}

function buildGraph(sources) {
  const moduleIds = new Set(sources.keys());
  const graph = new Map();
  const visiting = new Set();

  function visit(moduleId) {
    if (graph.has(moduleId)) return;
    if (visiting.has(moduleId)) {
      throw new Error(`Circular Nebula dependency detected at ${moduleId}`);
    }

    const source = sources.get(moduleId);
    if (source === undefined) {
      throw new Error(`Nebula module not found: ${moduleId}`);
    }

    visiting.add(moduleId);
    const rewritten = rewriteRequires(source, moduleId, moduleIds);
    graph.set(moduleId, rewritten);
    for (const dependencyId of rewritten.dependencies) {
      visit(dependencyId);
    }
    visiting.delete(moduleId);
  }

  visit(entryName);
  return graph;
}

export function buildBundle({ write = true } = {}) {
  const sources = loadSources();
  const graph = buildGraph(sources);
  const chunks = [
    "-- Standalone loadstring entry point generated by tools/build-bundle.mjs.",
    `-- Entry module: ${entryName}; bundled modules: ${graph.size}.`,
    "-- Do not edit this file directly. Change src/ and rebuild instead.",
    "local __modules = {}",
  ];

  for (const [id, module] of graph) {
    chunks.push(
      `__modules[${JSON.stringify(id)}] = function(require)`,
      module.source.trimEnd(),
      "end",
    );
  }

  chunks.push(
    "local __cache = {}",
    "local __loading = {}",
    "local __nil = {}",
    "local function __require(name)",
    "    local cached = __cache[name]",
    "    if cached ~= nil then",
    "        return cached == __nil and nil or cached",
    "    end",
    "    assert(not __loading[name], (\"Nebula bundled module cycle: %s\"):format(tostring(name)))",
    "    local factory = __modules[name]",
    '    assert(factory, ("Nebula bundled module not found: %s"):format(tostring(name)))',
    "    __loading[name] = true",
    "    local value = factory(__require)",
    "    __loading[name] = nil",
    "    __cache[name] = value == nil and __nil or value",
    "    return value",
    "end",
    `return __require(${JSON.stringify(entryName)})`,
  );

  const output = `${chunks.join("\n\n")}\n`;
  if (write) {
    fs.mkdirSync(path.dirname(outputPath), { recursive: true });
    fs.writeFileSync(outputPath, output);
  }

  return {
    output,
    outputPath,
    entryName,
    moduleIds: [...graph.keys()],
    graph,
  };
}

const invokedDirectly =
  process.argv[1] &&
  pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url;

if (invokedDirectly) {
  const result = buildBundle();
  console.info(
    `Built dist/Nebula.lua with ${result.moduleIds.length} reachable modules.`,
  );
}